      ro: ["Construită în jurul anului 1570", "Aparține epocii dinastiei Șeibanide", "Portalul are o înălțime de 20 de metri", "Situată lângă bazarul istoric Chorsu", "Restaurată major în secolul al XX-lea", "Funcționează ca școală islamică activă"],
      en: ["Built around the year 1570", "Dated to the Shaybanid dynasty era", "The entrance portal is 20 meters high", "Located adjacent to the Chorsu Bazaar", "Extensively restored in the 20th century", "Currently operates as a religious school"],
      es: ["Construida entre 1568 y 1570 bajo Abdullah Khan II.", "Altura del iwan principal: aprox. 30 metros", "Número de celdas para estudiantes: más de 100", "Restaurada en la década de 1990", "Parte del Patrimonio de la Humanidad de la UNESCO desde 1993", "Superficie del patio interior: unos 40x40 metros"],
      pt: ["Construída em 1568-1570 sob Abdullah Khan II.", "Altura do iwan principal: cerca de 30 metros", "Número de celas para estudantes: mais de 100", "Restaurada na década de 1990", "Parte do Património Mundial da UNESCO desde 1993", "Área do pátio interior: cerca de 40x40 metros"],
      fr: ["Construite entre 1568 et 1570 sous Abdullah Khan II.", "Hauteur de l'iwan principal : env. 30 mètres.", "Nombre de cellules d'étudiants : plus de 100.", "Restaurée dans les années 1990.", "Inscrite au patrimoine mondial de l'UNESCO depuis 1993.", "Superficie de la cour intérieure : environ 40x40 mètres."],
