    description: { de: "Eine der ältesten erhaltenen Moscheen in Buchara, die unter dem Bodenniveau liegt und vorislamische Einflüsse zeigt.", hu: "Buhara egyik legrégebbi fennmaradt mecsete, amely a talajszint alatt helyezkedik el, és iszlám előtti hatásokat mutat.", ro: "Una dintre cele mai vechi moschei păstrate din Buhara, aflată sub nivelul solului și care prezintă influențe pre-islamice.", en: "One of the oldest surviving mosques in Bukhara, situated below ground level and showing pre-Islamic influences." , es: "Una de las mezquitas más antiguas conservadas en Bujará, situada bajo el nivel del suelo y con influencias preislámicas.", pt: "Uma das mesquitas mais antigas preservadas em Bucara, situada abaixo do nível do solo e exibindo influências pré-islâmicas.", fr: "L'une des plus anciennes mosquées conservées de Boukhara, située sous le niveau du sol et présentant des influences préislamiques."},
    facts: {
      de: ["Der älteste Teil stammt aus dem 9. Jahrhundert.", "Wurde auf den Ruinen eines zoroastrischen Tempels erbaut.", "Beherbergt heute ein Teppichmuseum."],
      hu: ["A legrégebbi része a 9. századból származik.", "Egy zoroasztriánus templom romjaira épült.", "Ma egy szőnyegmúzeumnak ad otthont."],
      ro: ["Cea mai veche parte datează din secolul al IX-lea.", "A fost construită pe ruinele unui templu zoroastrian.", "Astăzi găzduiește un muzeu al covoarelor."],
      en: ["The oldest part dates back to the 9th century.", "Built on the ruins of a Zoroastrian temple.", "Today it houses a carpet museum."],
      es: ["La parte más antigua data del siglo IX.", "Fue construida sobre las ruinas de un templo zoroastriano.", "Alberga hoy en día un museo de alfombras."],
      pt: ["A parte mais antiga data do século IX.", "Foi construída sobre as ruínas de um templo zoroastriano.", "Abriga hoje um museu de tapetes."],
      fr: ["La partie la plus ancienne date du IXe siècle.", "A été construite sur les ruines d'un temple zoroastrien.", "Abrite aujourd'hui un musée du tapis."],
    }, image: "/poi-images/magok-i-attari-landmarks-v2.webp",
    descriptionAdvanced: {
      de: "Magok-i-Attari ist die älteste erhaltene Moschee in Buchara und ein faszinierendes Dokument der religiösen Geschichte der Stadt. Der Name bedeutet „Grube der Parfümeure“ und rührt daher, dass das Gebäude heute unter dem aktuellen Straßenniveau liegt. Sie wurde im 12. Jahrhundert auf den Überresten eines vorislamischen zoroastrischen Tempels errichtet, was die spirituelle Kontinuität des Ortes unterstreicht. Die Fassade der Moschee ist ein Meisterwerk der choresmischen Ziegelbaukunst, verziert mit komplexen geometrischen Mustern und Inschriften. Interessanterweise wurde der Ort im Mittelalter sowohl von Muslimen als auch von Juden gemeinsam für Gebete genutzt, was die damalige religiöse Toleranz in Buchara widerspiegelt. Bei Ausgrabungen im Jahr 1930 wurde die prachtvolle Südfassade freigelegt, die zuvor jahrhundertelang unter Sand und Schutt verborgen war. Heute beherbergt das Gebäude ein Teppichmuseum, das die jahrhundertealte Tradition der Webkunst in Usbekistan dokumentiert.",
      hu: "A Magok-i-Attari mecset Buhara legrégebbi fennmaradt mecsetje, amely a város gazdag és összetett vallástörténetének egyik legfontosabb emléke. A név jelentése „az illatszerárusok mélyedése”, utalva arra, hogy az épület jelentősen a jelenlegi utcaszint alatt helyezkedik el. A 12. században épült egy korábbi zoroasztriánus templom helyén, bizonyítva a hely szakrális folytonosságát. A mecset homlokzata a téglából készült díszítőművészet remekműve, bonyolult geometrikus mintákkal és ősi feliratokkal. A középkorban különlegessége volt, hogy a muszlimok és a zsidók közösen használták imádkozásra, ami a korabeli vallási toleranciát jelzi. 1930-ban egy régészeti feltárás során bukkantak rá a déli homlokzatra, amely évszázadokon át homok alatt rejtőzött. Jelenleg szőnyegmúzeumnak ad otthont, ahol Üzbegisztán híres kézzel szőtt alkotásait tekinthetik meg a látogatók.",
      ro: "Magok-i-Attari este cea mai veche moschee păstrată din Buhara, fiind un monument fascinant al istoriei religioase a Asiei Centrale. Numele său se traduce prin „Groapa Parfumierilor”, denumire datorată faptului că nivelul solului a crescut de-a lungul secolelor, lăsând clădirea sub nivelul străzii actuale. Construită în secolul al XII-lea pe locul unui vechi templu zoroastrian, moscheea atestă succesiunea credințelor în regiune. Fațada sa sudică este considerată o capodoperă a zidăriei în relief, cu motive geometrice complexe realizate din cărămidă nearsă. O legendă istorică menționează că, până la construirea primei sinagogi, comunitatea evreiască din oraș folosea acest lăcaș împreună cu musulmanii pentru rugăciune. După restaurările din secolul al XX-lea, clădirea a fost transformată în muzeu al covoarelor, expunând piese rare ce reflectă tradiția milenară a țesutului în Uzbekistan.",
      en: "Magok-i-Attari is the oldest surviving mosque in Bukhara and a remarkable witness to the city's complex religious history. Its name means \"Pit of the Herbalists,\" referring to the fact that the building now sits significantly below the modern street level due to accumulated layers of history. Built in the 12th century on the site of a pre-Islamic Zoroastrian temple, the mosque represents the spiritual evolution of the region. The southern facade is a masterpiece of early Islamic brickwork, featuring intricate patterns and terracotta ornaments that were hidden under sand for centuries until excavated in the 1930s. Interestingly, historical accounts suggest that the mosque was shared by Muslims and Jews for prayer before the city's first synagogue was built. Today, the building houses a museum of carpets, showcasing the rich textile traditions of Bukhara and Central Asia.",
      es: "Magok-i-Attari es una mezquita del siglo IX en Bujará, una de las más antiguas de Asia Central. Se encuentra en el centro histórico de la ciudad. La mezquita fue construida sobre las ruinas de un templo zoroastriano. En el siglo XII fue ampliada y posteriormente restaurada en varias ocasiones. El nombre significa 'mezquita en el foso de los perfumistas'. El edificio tiene una fachada sencilla con decoraciones de ladrillo. Hoy en día es un museo de alfombras y textiles.",
      pt: "Magok-i-Attari é uma mesquita do século IX em Bucara, uma das mais antigas da Ásia Central. Situa-se no centro histórico da cidade. A mesquita foi construída sobre as ruínas de um templo zoroastriano. No século XII foi ampliada e, mais tarde, restaurada várias vezes. O nome significa 'mesquita no fosso dos perfumistas'. O edifício tem uma fachada simples com decorações em tijolo. Hoje é um museu de tapetes e têxteis.",
      fr: "Magok-i-Attari est une mosquée du IXe siècle située à Boukhara, l'une des plus anciennes d'Asie centrale. Elle se trouve dans le centre historique de la ville. La mosquée a été érigée sur les ruines d'un temple zoroastrien. Elle a été agrandie au XIIe siècle, puis restaurée à plusieurs reprises. Son nom signifie « mosquée dans la fosse des parfumeurs ». Le bâtiment présente une façade sobre ornée de briques décoratives. Aujourd'hui, il abrite un musée de tapis et de textiles.",
    },
