      es: ["El bazar tiene una superficie de aprox. 1 hectárea.", "Se encuentra cerca de la plaza Registán.", "Diariamente visitan el mercado unas 5.000 personas.", "El bazar fue renovado en 2014.", "Horario: de 6:00 a 20:00.", "La altitud de Samarcanda es de 702 metros."],
